const section = (enTitle: string, arTitle: string, enBody: string, arBody: string, visual: CurriculumLesson["explanation"][number]["visual"]) => ({ title: L(enTitle, arTitle), body: L(enBody, arBody), visual });
const unit1Teaching = {
  "it-and-society": {
    objectives: [L("Explain the major stages in the development of information technology.", "اشرح المراحل الرئيسية في تطور تكنولوجيا المعلومات."), L("Explain how each stage affected society.", "اشرح كيف أثّرت كل مرحلة في المجتمع."), L("Describe important social changes caused by information technology.", "صف التغيرات الاجتماعية المهمة التي سببتها تكنولوجيا المعلومات."), L("Explain important emerging technologies.", "اشرح التقنيات الناشئة المهمة.")],
    explanation: [
      section("The story of information technology", "قصة تكنولوجيا المعلومات", "Information technology did not arrive in its modern form at one moment. It developed in stages: room-sized computers used by specialists, personal computers, the connected Internet and Web, smartphones, and cloud services. Each stage changed more than the machine. It changed how people communicate, work, learn, shop, pay, find information, and use public and private services.", "لم تظهر تكنولوجيا المعلومات بشكلها الحديث دفعة واحدة. بل تطورت على مراحل: حواسيب ضخمة يستخدمها المتخصصون، ثم الحواسيب الشخصية، ثم الإنترنت والويب المتصلان، ثم الهواتف الذكية، ثم الخدمات السحابية. ولم تغيّر كل مرحلة الأجهزة فقط، بل غيّرت التواصل والعمل والتعلم والتسوق والدفع والوصول إلى المعلومات والخدمات.", "timeline"),
      section("1940s–1960s: specialist computers", "الأربعينيات إلى الستينيات: حواسيب المتخصصين", "Early computers, including ENIAC, were extremely large and used technologies such as vacuum tubes. They could occupy a room and were expensive to build and operate. Their main uses were military calculations, scientific computation, and specialized technical work. Computing existed, but ordinary people rarely had direct access to it; it was mainly controlled by governments, universities, and major organizations.", "كانت الحواسيب المبكرة، ومنها ENIAC، ضخمة جدًا وتستخدم تقنيات مثل الصمامات المفرغة. وقد تشغل غرفة كاملة وكانت مكلفة في البناء والتشغيل. استُخدمت أساسًا في الحسابات العسكرية والعلمية والأعمال التقنية المتخصصة. كانت الحوسبة موجودة، لكن عامة الناس نادرًا ما وصلوا إليها؛ إذ ارتبطت بالحكومات والجامعات والمؤسسات الكبيرة.", "timeline"),
      section("1970s–1990s: personal then connected", "السبعينيات إلى التسعينيات: حوسبة شخصية ثم متصلة", "Personal computers changed who could use technology. Individuals could write documents, store information, run programs, and study rather than relying only on an institution. In the 1990s the commercial Internet and World Wide Web connected those machines across distance. Email, global information access, online services, and easier communication marked the transition from personal computing to connected computing.", "غيّرت الحواسيب الشخصية من يستطيع استخدام التقنية. فأصبح بإمكان الأفراد كتابة المستندات وتخزين المعلومات وتشغيل البرامج والدراسة بدل الاعتماد على مؤسسة فقط. وفي التسعينيات ربط الإنترنت التجاري والويب هذه الأجهزة عبر المسافات. وكان البريد الإلكتروني والوصول العالمي للمعلومات والخدمات عبر الإنترنت وسهولة التواصل انتقالًا من الحوسبة الشخصية إلى الحوسبة المتصلة.", "timeline"),
      section("2000s onward: mobile and cloud", "منذ الألفية الجديدة: المحمول والسحابة", "Smartphones put Internet-connected computing into a device people could carry. A phone combines communication, camera, maps, payment, social networking, entertainment, and apps, so computing became part of everyday life rather than an activity at a desk. Cloud computing later made processing power, storage, and software available as services through the Internet. The cloud is not abstract: cloud services run on real servers in data centres. It supports large storage, collaboration, data analysis, online services, and modern AI.", "وضعت الهواتف الذكية الحوسبة المتصلة بالإنترنت في جهاز يمكن حمله. فهي تجمع الاتصال والكاميرا والخرائط والدفع والتواصل الاجتماعي والترفيه والتطبيقات، فأصبحت الحوسبة جزءًا من الحياة اليومية لا نشاطًا على مكتب فقط. وجعلت الحوسبة السحابية قدرة المعالجة والتخزين والبرمجيات خدمات عبر الإنترنت. والسحابة ليست شيئًا غامضًا؛ فخدماتها تعمل على خوادم حقيقية في مراكز بيانات. وهي تدعم التخزين الكبير والتعاون وتحليل البيانات والخدمات والذكاء الاصطناعي الحديث.", "timeline"),
      section("Moore's Law and physical limits", "قانون مور والحدود الفيزيائية", "Moore's Law is the historical observation that the number of transistors on an integrated circuit roughly doubled about every two years for many years. A transistor is a tiny electronic component in a chip; more transistors helped computers become more capable. This trend faces limits: at extremely small scales, quantum tunnelling can allow electrons through barriers, and leakage current can escape unintentionally. Engineers therefore use approaches such as multiple processor cores and parallel processing instead of depending only on one ever-smaller core.", "قانون مور ملاحظة تاريخية مفادها أن عدد الترانزستورات في الدائرة المتكاملة كان يتضاعف تقريبًا كل عامين لسنوات كثيرة. والترانزستور مكوّن إلكتروني صغير داخل الشريحة؛ وزيادة عدده ساعدت الحواسيب على أن تصبح أكثر قدرة. لكن لهذا الاتجاه حدود: فعند المقاييس الصغيرة جدًا قد تسمح ظاهرة النفق الكمي للإلكترونات بعبور الحواجز، وقد يتسرب التيار دون قصد. لذلك يستخدم المهندسون أساليب مثل الأنوية المتعددة والمعالجة المتوازية بدل الاعتماد على نواة واحدة أصغر باستمرار.", "moore"),
      section("Technology changes society", "التقنية تغيّر المجتمع", "Social networking services (SNS) let connected users post and share information rapidly. E-commerce means buying and selling goods or services through the Internet. Remote work uses online communication and resources away from a traditional workplace, while online learning delivers lessons and materials through the Internet. Cashless payment uses cards, electronic money, QR codes, or mobile apps. These changes can be convenient, but a fair design also asks who may be excluded—for example, a person without a bank card, smartphone, connection, or digital skills.", "تتيح شبكات التواصل الاجتماعي (SNS) للمستخدمين المتصلين نشر المعلومات ومشاركتها بسرعة. والتجارة الإلكترونية تعني شراء السلع أو الخدمات وبيعها عبر الإنترنت. ويعتمد العمل عن بُعد على الاتصال والموارد الرقمية خارج مكان العمل التقليدي، بينما يقدم التعلم عبر الإنترنت الدروس والمواد من خلال الشبكة. ويستخدم الدفع غير النقدي البطاقات أو النقود الإلكترونية أو رموز QR أو تطبيقات الهاتف. وهذه التغيرات مريحة، لكن التصميم العادل يسأل أيضًا: من قد يُستبعد، مثل من لا يملك بطاقة بنكية أو هاتفًا ذكيًا أو اتصالًا أو مهارات رقمية؟", "compare"),
      section("Autonomous driving: cloud and edge", "القيادة الذاتية: السحابة والطرف", "An autonomous vehicle uses cameras and sensors to collect information, recognize its surroundings, decide how to drive, and control the vehicle. Some decisions must be made immediately. Cloud processing can offer powerful remote resources, but sending every sensor reading across the Internet and waiting for a reply can create dangerous delay. Edge computing processes important data close to where it is generated—inside or near the vehicle—so a local system can make a rapid decision. Edge is especially useful when delay matters.", "تستخدم المركبة ذاتية القيادة الكاميرات والمستشعرات لجمع المعلومات والتعرف إلى البيئة واتخاذ قرار القيادة والتحكم بالمركبة. ويجب أن تتخذ بعض القرارات فورًا. قد توفر المعالجة السحابية موارد بعيدة قوية، لكن إرسال كل قراءة مستشعر عبر الإنترنت وانتظار الرد قد يسبب تأخرًا خطيرًا. تعالج الحوسبة الطرفية البيانات المهمة قرب مكان إنشائها، داخل المركبة أو بجوارها، حتى يتخذ النظام المحلي قرارًا سريعًا. وتفيد الحوسبة الطرفية خصوصًا عندما يكون التأخر مهمًا.", "edge"),
      section("AR, VR, and quantum computing", "الواقع المعزز والافتراضي والحوسبة الكمية", "Augmented reality (AR) adds digital information to the real environment: AR adds to reality. Virtual reality (VR) places the user in an immersive computer-generated environment: VR immerses the user in a virtual world. Traditional computers use bits that represent one state at a time. Quantum computers use qubits and ideas such as superposition. They are being developed for certain computations that are difficult or impractical for traditional computers; they do not simply make every task faster.", "يضيف الواقع المعزز (AR) معلومات رقمية إلى البيئة الحقيقية: فالواقع المعزز يضيف إلى الواقع. أما الواقع الافتراضي (VR) فيضع المستخدم داخل بيئة رقمية غامرة: فهو يغمره في عالم افتراضي. تستخدم الحواسيب التقليدية بتاتًا تمثل حالة واحدة في كل مرة. وتستخدم الحواسيب الكمية كيوبتات ومبادئ مثل التراكب. ويجري تطويرها لمسائل محددة صعبة أو غير عملية للحواسيب التقليدية؛ ولا تجعل كل مهمة أسرع ببساطة.", "arvr"),
    ],
    facts: ["personal computer", "Internet and Web", "smartphone", "cloud computing", "Moore's Law", "edge computing", "AR", "VR", "qubit", "cashless payment"],
  },
  "how-ai-works": {
    objectives: [L("Explain how AI, Machine Learning, Deep Learning, and Generative AI are related.", "اشرح العلاقة بين الذكاء الاصطناعي وتعلم الآلة والتعلم العميق والذكاء الاصطناعي التوليدي."), L("Explain how models learn from data and why generated content must be checked.", "اشرح كيف تتعلم النماذج من البيانات ولماذا يجب التحقق من المحتوى المولّد.")],
    explanation: [
      section("AI is a broad field", "الذكاء الاصطناعي مجال واسع", "Artificial Intelligence (AI) is a general term for computer technologies that perform or reproduce aspects of intelligent human behaviour, such as learning, reasoning, judgment, speech recognition, image recognition, and translation. AI is not one program or one method. Modern systems are generally specialised for particular tasks; they do not possess every kind of human intelligence.", "الذكاء الاصطناعي (AI) مصطلح عام لتقنيات حاسوبية تؤدي أو تحاكي جوانب من السلوك الإنساني الذكي، مثل التعلم والاستدلال والحكم والتعرف على الكلام والصور والترجمة. وليس الذكاء الاصطناعي برنامجًا أو طريقة واحدة. فالأنظمة الحديثة متخصصة غالبًا في مهام محددة ولا تمتلك كل أنواع الذكاء البشري.", "hierarchy"),
      section("A nested relationship", "علاقة متداخلة", "The key relationship is nested, not four unrelated labels: AI contains Machine Learning; Machine Learning contains Deep Learning; and modern Generative AI is built using Deep Learning. Moving inward means becoming more specialised. A student should therefore never describe Deep Learning as separate from Machine Learning.", "العلاقة الأساسية متداخلة وليست أربع تسميات منفصلة: يضم الذكاء الاصطناعي تعلم الآلة، ويضم تعلم الآلة التعلم العميق، ويبنى الذكاء الاصطناعي التوليدي الحديث باستخدام التعلم العميق. ويعني الانتقال إلى الداخل مزيدًا من التخصص. لذلك لا ينبغي وصف التعلم العميق على أنه منفصل عن تعلم الآلة.", "hierarchy"),
      section("Machine Learning: learning patterns", "تعلم الآلة: تعلم الأنماط", "A rule-based program follows instructions written by people for every case. Machine Learning learns patterns from data instead. Those patterns can be used to predict, classify, recommend, or make a judgement about a new case. A spam filter can learn features of unwanted messages, and a recommendation system can learn from earlier viewing or purchasing behaviour. The tasks differ, but both use learned patterns to make a prediction.", "يتبع البرنامج القائم على القواعد تعليمات يكتبها البشر لكل حالة. أما تعلم الآلة فيتعلم الأنماط من البيانات. ويمكن استخدام هذه الأنماط للتنبؤ أو التصنيف أو التوصية أو إصدار حكم بشأن حالة جديدة. فقد يتعلم مرشح البريد المزعج خصائص الرسائل غير المرغوبة، وقد يتعلم نظام التوصية من المشاهدة أو الشراء السابق. تختلف المهمة، لكن كليهما يستخدم أنماطًا متعلمة لإجراء تنبؤ.", "rules"),
      section("Deep Learning and neural networks", "التعلم العميق والشبكات العصبية", "Deep Learning is an advanced type of Machine Learning that uses neural networks and can learn complex patterns from large-scale data. It is useful in applications such as image analysis for autonomous driving and advanced speech systems. A neural network is computationally inspired by interconnected nerve cells in the brain: many simple computational units are connected and learn from data. It is not literally a human brain.", "التعلم العميق نوع متقدم من تعلم الآلة يستخدم الشبكات العصبية ويمكنه تعلم أنماط معقدة من بيانات واسعة. ويفيد في تطبيقات مثل تحليل الصور للقيادة الذاتية وأنظمة الكلام المتقدمة. والشبكة العصبية مستوحاة حاسوبيًا من خلايا عصبية مترابطة في الدماغ: تتصل وحدات حسابية بسيطة كثيرة وتتعلم من البيانات. لكنها ليست دماغًا بشريًا حرفيًا.", "neural"),
      section("Generative AI", "الذكاء الاصطناعي التوليدي", "Generative AI uses deep learning to generate new output based on patterns learned from data. It can generate text, images, audio, and programs. This distinguishes it from a system that only recognises or classifies existing information. A chat system can produce a response and an image system can produce a new image, but the output is a prediction of likely patterns, not a guarantee of truth.", "يستخدم الذكاء الاصطناعي التوليدي التعلم العميق لإنتاج مخرجات جديدة استنادًا إلى الأنماط المتعلمة من البيانات. ويمكنه إنتاج نصوص وصور وصوت وبرامج. وهذا يميزه عن نظام يتعرف فقط إلى المعلومات الموجودة أو يصنفها. فقد ينتج نظام محادثة استجابة أو ينتج نظام صور صورة جديدة، لكن المخرج توقع لأنماط محتملة وليس ضمانًا للحقيقة.", "generative"),
      section("Hallucination and verification", "الهلوسة والتحقق", "A hallucination is AI-generated information that sounds convincing but is inaccurate or unsupported. A confident tone is not evidence. Check important AI-generated claims using trustworthy sources, especially for school reports, research, factual information, or important decisions. Never give a system private information merely to obtain a convenient answer.", "الهلوسة هي معلومات يولدها الذكاء الاصطناعي تبدو مقنعة لكنها غير دقيقة أو بلا دليل. فالنبرة الواثقة ليست برهانًا. تحقّق من الادعاءات المهمة التي يولدها الذكاء الاصطناعي باستخدام مصادر موثوقة، خاصة في التقارير المدرسية والبحث والمعلومات الواقعية والقرارات المهمة. ولا تعطِ النظام معلومات خاصة لمجرد الحصول على إجابة مريحة.", "caution"),
    ],
    facts: ["Artificial Intelligence", "Machine Learning", "Deep Learning", "neural network", "Generative AI", "hallucination", "rule-based program", "prediction", "classification", "verification"],
  },
  "ai-in-life": {
    objectives: [L("Explain common AI uses in daily life and industry.", "اشرح استخدامات الذكاء الاصطناعي الشائعة في الحياة اليومية والصناعة."), L("Explain what AI does well and where human judgment remains necessary.", "اشرح ما يجيده الذكاء الاصطناعي وأين يبقى الحكم البشري ضروريًا.")],
    explanation: [
      section("AI is already around us", "الذكاء الاصطناعي موجود حولنا", "AI is not only a future technology. Everyday services use it for recommendations, voice assistants, machine translation, and face recognition. Industries use it in healthcare, agriculture, manufacturing, and logistics. The key question is not only whether a system is impressive: what pattern is it using, what data does it need, and where must a person check the result?", "الذكاء الاصطناعي ليس تقنية مستقبلية فقط. تستخدمه خدمات يومية في التوصيات والمساعدات الصوتية والترجمة الآلية والتعرف على الوجه. وتستخدمه قطاعات الرعاية الصحية والزراعة والتصنيع واللوجستيات. والسؤال الأساسي ليس هل النظام مبهر فقط، بل ما النمط الذي يستخدمه وما البيانات التي يحتاجها وأين يجب أن يراجع الإنسان النتيجة؟", "everyday"),
      section("Everyday services", "الخدمات اليومية", "A recommendation system predicts preferences from behaviour such as videos watched, products bought, or music played; it does not simply know what a person likes. A voice assistant recognises speech, interprets a command, and performs an action or returns information. Machine translation identifies language patterns to generate a translation. Face recognition detects or identifies faces, for example when unlocking a phone, but faces are personal information and raise privacy and fairness questions.", "يتنبأ نظام التوصية بالتفضيلات من السلوك مثل الفيديوهات المشاهدة أو المنتجات المشتراة أو الموسيقى المشغلة؛ فهو لا يعرف ما يحبه الشخص ببساطة. ويتعرف المساعد الصوتي إلى الكلام ويفسر الأمر ثم ينفذ إجراءً أو يعيد معلومات. وتحدد الترجمة الآلية أنماط اللغة لتنتج ترجمة. ويكشف التعرف على الوجه الوجوه أو يحددها، مثل فتح الهاتف، لكن الوجوه معلومات شخصية تثير أسئلة الخصوصية والإنصاف.", "recommendation-flow"),
      section("Healthcare and agriculture", "الرعاية الصحية والزراعة", "AI can analyse medical images such as X-rays or CT images and may help detect patterns associated with disease. It can also support drug discovery. However, health decisions affect people directly, so AI can support a doctor but responsibility must not disappear. In agriculture, AI can help predict harvest timing and detect pests or disease from data and images, giving farmers evidence for decisions rather than replacing their knowledge.", "يمكن للذكاء الاصطناعي تحليل الصور الطبية مثل الأشعة السينية أو المقطعية وقد يساعد على كشف أنماط مرتبطة بالمرض. ويمكنه دعم اكتشاف الأدوية. لكن القرارات الصحية تؤثر مباشرة في الناس، لذا يمكنه دعم الطبيب ولا ينبغي أن تختفي المسؤولية. وفي الزراعة يمكنه المساعدة في توقع موعد الحصاد وكشف الآفات أو الأمراض من البيانات والصور، فيعطي المزارعين أدلة للقرار ولا يستبدل معرفتهم.", "industry"),
      section("Manufacturing and logistics", "التصنيع واللوجستيات", "In manufacturing, automated quality inspection can identify defects or unusual patterns, while predictive maintenance uses machine data to anticipate possible failures before they happen. In logistics, systems can analyse information to choose delivery routes expected to be more efficient. These are predictions and recommendations based on available data; conditions can change, so people need to monitor the system and handle exceptional cases.", "في التصنيع يمكن لفحص الجودة الآلي تحديد العيوب أو الأنماط غير العادية، بينما تستخدم الصيانة التنبؤية بيانات الآلات لتوقع الأعطال قبل وقوعها. وفي اللوجستيات يمكن للأنظمة تحليل المعلومات لاختيار مسارات تسليم يتوقع أن تكون أكثر كفاءة. وهذه تنبؤات وتوصيات تستند إلى البيانات المتاحة؛ وقد تتغير الظروف، لذلك يجب أن يراقب الناس النظام ويتعاملوا مع الحالات الاستثنائية.", "operations-flow"),
      section("What AI does well", "ما يجيده الذكاء الاصطناعي", "AI is especially useful for finding and classifying patterns in complex data such as images and text; recognising and generating images, audio, and text; and probabilistic prediction. Probabilistic means an output estimates what is likely from patterns—it is not perfect certainty. A useful system can still be wrong, incomplete, or unsuitable for a particular person or situation.", "يفيد الذكاء الاصطناعي خاصة في إيجاد الأنماط وتصنيفها في بيانات معقدة مثل الصور والنصوص، وفي التعرف إلى الصور والصوت والنص وإنتاجها، وفي التنبؤ الاحتمالي. وتعني كلمة احتمالي أن المخرج يقدّر ما هو مرجح من الأنماط، وليس يقينًا كاملًا. وقد يكون النظام المفيد خاطئًا أو ناقصًا أو غير مناسب لشخص أو موقف معين.", "ai-strengths"),
      section("Where caution and people matter", "أين يلزم الحذر والإنسان", "AI needs careful human judgment when ethical choices, personal information, fairness, or responsibility are involved. Training data can be biased; generated answers can hallucinate; copyrighted training material can raise rights questions; and a black-box system can make it hard to understand a decision. People must define the goal, protect data, check important outputs, and remain responsible for high-impact decisions.", "يحتاج الذكاء الاصطناعي إلى حكم بشري حذر عندما تتعلق المسألة بالاختيارات الأخلاقية أو المعلومات الشخصية أو الإنصاف أو المسؤولية. فقد تكون بيانات التدريب متحيزة، وقد تهلوس الإجابات المولدة، وقد تثير مواد التدريب المحمية حقوقًا، وقد يصعب فهم قرار نظام الصندوق الأسود. ويجب أن يحدد الناس الهدف ويحمو البيانات ويتحققوا من المخرجات المهمة ويبقوا مسؤولين عن القرارات عالية الأثر.", "caution"),
    ],
    facts: ["recommendation system", "voice assistant", "machine translation", "face recognition", "medical image analysis", "predictive maintenance", "logistics", "probabilistic prediction", "privacy", "human judgment"],
  },
  "ai-ethics": {
    objectives: [L("Explain why bias, privacy, transparency, and accountability matter in AI.", "اشرح أهمية التحيز والخصوصية والشفافية والمساءلة في الذكاء الاصطناعي."), L("Apply the four basic principles of AI ethics to a realistic decision.", "طبّق المبادئ الأربعة الأساسية لأخلاقيات الذكاء الاصطناعي على قرار واقعي.")],
    explanation: [
      section("Why AI ethics matters", "لماذا تهم أخلاقيات الذكاء الاصطناعي", "AI systems increasingly make or support decisions that affect people, for example selecting job candidates, identifying people with face recognition, or analysing personal data. Technical accuracy alone is not enough: a powerful system can still create an unfair or harmful outcome. Responsible AI requires fairness, transparency, privacy protection, and accountability.", "تتخذ أنظمة الذكاء الاصطناعي قرارات تؤثر في الناس أو تدعمها، مثل اختيار المتقدمين للوظائف أو تحديد الأشخاص بالتعرف على الوجه أو تحليل البيانات الشخصية. ولا تكفي الدقة التقنية وحدها؛ فقد ينتج نظام قوي نتيجة غير عادلة أو ضارة. ويتطلب الذكاء الاصطناعي المسؤول الإنصاف والشفافية وحماية الخصوصية والمساءلة.", "ethics-overview"),
      section("Algorithmic bias", "التحيز الخوارزمي", "Algorithmic bias is an unfair pattern in AI judgments caused by data or system design. A hiring system trained on historical decisions that contained discrimination may learn and reproduce that pattern. If some groups are insufficiently represented in face-recognition training data, accuracy can differ between groups. AI learns from inputs and design choices, so unfair inputs can create unfair outputs.", "التحيز الخوارزمي نمط غير عادل في أحكام الذكاء الاصطناعي تسببه البيانات أو تصميم النظام. فقد يتعلم نظام توظيف دُرّب على قرارات تاريخية تضمنت تمييزًا هذا النمط ويعيده. وإذا لم تُمثل بعض الفئات تمثيلًا كافيًا في بيانات تدريب التعرف على الوجه فقد تختلف الدقة بين المجموعات. يتعلم الذكاء الاصطناعي من المدخلات وخيارات التصميم، لذلك قد تنتج المدخلات غير العادلة مخرجات غير عادلة.", "bias-intro"),
      section("Where bias comes from", "من أين يأتي التحيز", "Bias can come from training data that reflects historical discrimination, insufficient data for a group, or system-design choices. A variable may be inappropriate, or a proxy variable may indirectly stand for a protected characteristic. The pathway is important: biased or insufficient data or design leads a model to learn a pattern, which leads to biased judgement and possible harm. Testing outcomes for different groups is therefore essential.", "قد يأتي التحيز من بيانات تدريب تعكس تمييزًا تاريخيًا، أو من بيانات غير كافية لمجموعة ما، أو من خيارات تصميم النظام. فقد يكون المتغير غير مناسب، أو يكون متغير بديل يمثل بصورة غير مباشرة صفة محمية. والمسار مهم: فبيانات أو تصميم متحيز أو غير كافٍ يقود النموذج لتعلم نمط، ثم إلى حكم متحيز وضرر محتمل. لذلك يعد اختبار النتائج لمجموعات مختلفة أمرًا أساسيًا.", "bias"),
      section("Privacy and surveillance", "الخصوصية والمراقبة", "AI often relies on large amounts of data. Face-recognition cameras in public spaces may offer security or convenience, but can also identify and track people. Online services can collect searches, clicks, viewing behaviour, purchases, and location-related information. Convenience and privacy can conflict, so organisations must decide what is collected, why it is needed, how it is used, and who can access it.", "يعتمد الذكاء الاصطناعي كثيرًا على كميات كبيرة من البيانات. قد توفر كاميرات التعرف على الوجه في الأماكن العامة أمنًا أو راحة، لكنها قد تحدد الأشخاص وتتبعهم أيضًا. ويمكن للخدمات عبر الإنترنت جمع عمليات البحث والنقرات وسلوك المشاهدة والمشتريات والمعلومات المتعلقة بالموقع. وقد تتعارض الراحة مع الخصوصية، لذا يجب على المؤسسات تحديد ما الذي يُجمع ولماذا يلزم وكيف يستخدم ومن يصل إليه.", "privacy-path"),
      section("Black box and Explainable AI", "الصندوق الأسود والذكاء القابل للتفسير", "The black-box problem occurs when an AI gives a result but people cannot easily understand why. A rejected job application without reasons is difficult to check, challenge, or connect to responsibility. Explainable AI (XAI) aims to give people meaningful information about why a model reached a judgment. XAI supports transparency, but an explanation must be useful and honest rather than merely technical words.", "تظهر مشكلة الصندوق الأسود عندما يعطي الذكاء الاصطناعي نتيجة ولا يستطيع الناس فهم سببها بسهولة. فرفض طلب وظيفة بلا أسباب يصعب التحقق منه أو الاعتراض عليه أو ربطه بالمسؤولية. ويهدف الذكاء الاصطناعي القابل للتفسير (XAI) إلى إعطاء الناس معلومات مفهومة عن سبب وصول النموذج إلى الحكم. ويدعم XAI الشفافية، لكن يجب أن يكون الشرح مفيدًا وصادقًا لا مجرد كلمات تقنية.", "xai"),
      section("Responsibility and accountability", "المسؤولية والمساءلة", "When an AI-supported decision is wrong or unfair, possible responsible parties include the developer, organisation using the system, operator, and user. There may not be one simple answer, but using AI never makes human responsibility disappear. Accountability means someone is answerable for monitoring the system, responding to harm, and improving it.", "عندما يكون القرار المدعوم بالذكاء الاصطناعي خاطئًا أو غير عادل، فقد تشمل الأطراف المسؤولة المطور والمؤسسة المستخدمة للنظام والمشغّل والمستخدم. وقد لا توجد إجابة واحدة بسيطة، لكن استخدام الذكاء الاصطناعي لا يلغي المسؤولية البشرية. وتعني المساءلة أن يكون شخص أو جهة مسؤولًا عن مراقبة النظام والاستجابة للضرر وتحسينه.", "accountability-flow"),
      section("Four principles together", "المبادئ الأربعة معًا", "Fairness avoids unjust discrimination. Transparency makes important decisions understandable. Privacy protection handles personal information appropriately. Accountability ensures someone is answerable. For a hiring AI, ask: were groups treated fairly; can the decision be understood; was applicant data protected; and who fixes a harmful outcome? Responsible AI needs all four principles together, not only one.", "يتجنب الإنصاف التمييز غير المبرر. وتجعل الشفافية القرارات المهمة مفهومة. وتحمي الخصوصية المعلومات الشخصية على نحو مناسب. وتضمن المساءلة وجود جهة تُسأل. وفي نظام توظيف بالذكاء الاصطناعي اسأل: هل عوملت المجموعات بإنصاف؟ هل يمكن فهم القرار؟ هل حميت بيانات المتقدمين؟ ومن يصلح نتيجة ضارة؟ يحتاج الذكاء الاصطناعي المسؤول إلى المبادئ الأربعة معًا لا إلى واحد فقط.", "ethics"),
    ],
    facts: ["algorithmic bias", "training data", "privacy", "black-box problem", "Explainable AI", "fairness", "transparency", "accountability", "proxy variable", "responsibility"],
  },
} as const;

function unit1Question(id: string, type: CurriculumQuestion["type"], en: string, ar: string, answer: string, explanationEn: string, explanationAr: string, choices?: [string, string, string, string] | [string, string]) : CurriculumQuestion {
  return { id, type, prompt: L(en, ar), answer, explanation: L(explanationEn, explanationAr), choices: choices?.map((text, index) => ({ id: String.fromCharCode(97 + index), text: L(text, text) })) };
}
const unit1Summaries: Record<keyof typeof unit1Teaching, LocalizedText[]> = {
  "it-and-society": [L("Early specialist computers → personal computers → Internet/Web → smartphones → cloud services.", "حواسيب المتخصصين → الحواسيب الشخصية → الإنترنت والويب → الهواتف الذكية → الخدمات السحابية."), L("Cloud computing delivers real computing resources from data-centre servers as online services.", "تقدم الحوسبة السحابية موارد حوسبة حقيقية من خوادم مراكز البيانات كخدمات عبر الإنترنت."), L("Moore's Law describes historical transistor growth; physical limits encourage multi-core and parallel approaches.", "يصف قانون مور نمو الترانزستورات تاريخيًا؛ وتشجع الحدود الفيزيائية أساليب الأنوية المتعددة والمعالجة المتوازية."), L("SNS, e-commerce, remote work, online learning, and cashless payment change daily life but can create access gaps.", "تغير شبكات التواصل والتجارة الإلكترونية والعمل عن بُعد والتعلم عبر الإنترنت والدفع غير النقدي الحياة اليومية، لكنها قد تخلق فجوات وصول."), L("Edge computing makes local decisions quickly; AR adds to reality, VR immerses, and quantum computing targets selected hard problems.", "تتخذ الحوسبة الطرفية قرارات محلية سريعة؛ ويضيف AR إلى الواقع ويغمر VR المستخدم، وتستهدف الحوسبة الكمية مسائل صعبة محددة.")],
  "how-ai-works": [L("AI is the broad field; Machine Learning is inside AI; Deep Learning is inside Machine Learning.", "الذكاء الاصطناعي هو المجال الأوسع؛ وتعلم الآلة داخله؛ والتعلم العميق داخل تعلم الآلة."), L("Machine Learning learns patterns from data to predict, classify, recommend, or judge new cases.", "يتعلم تعلم الآلة الأنماط من البيانات للتنبؤ أو التصنيف أو التوصية أو الحكم على حالات جديدة."), L("Deep Learning uses neural networks and large-scale data for complex patterns.", "يستخدم التعلم العميق الشبكات العصبية والبيانات الواسعة للأنماط المعقدة."), L("Generative AI, built with deep learning, can create text, images, audio, and programs.", "يمكن للذكاء الاصطناعي التوليدي المبني بالتعلم العميق إنتاج نصوص وصور وصوت وبرامج."), L("A hallucination can sound convincing yet be false, so important AI output must be verified.", "قد تبدو الهلوسة مقنعة لكنها خاطئة، لذلك يجب التحقق من مخرجات الذكاء الاصطناعي المهمة.")],
  "ai-in-life": [L("AI supports recommendations, voice assistants, translation, and face recognition in everyday services.", "يدعم الذكاء الاصطناعي التوصيات والمساعدات الصوتية والترجمة والتعرف على الوجه في الخدمات اليومية."), L("Healthcare, agriculture, manufacturing, and logistics use AI to analyse patterns and support decisions.", "تستخدم الرعاية الصحية والزراعة والتصنيع واللوجستيات الذكاء الاصطناعي لتحليل الأنماط ودعم القرارات."), L("AI is strong at classification, recognition, generation, and probabilistic prediction—not certainty.", "يجيد الذكاء الاصطناعي التصنيف والتعرف والتوليد والتنبؤ الاحتمالي، لا اليقين."), L("Privacy, biased data, hallucination, copyright, black-box decisions, and responsibility require caution.", "تتطلب الخصوصية والبيانات المتحيزة والهلوسة وحقوق النشر وقرارات الصندوق الأسود والمسؤولية الحذر."), L("Human judgment remains essential for high-impact decisions affecting people.", "يبقى الحكم البشري ضروريًا للقرارات عالية الأثر التي تمس الناس.")],
  "ai-ethics": [L("Bias can come from historical data, insufficient representation, and system-design choices.", "قد يأتي التحيز من البيانات التاريخية أو التمثيل غير الكافي أو خيارات تصميم النظام."), L("Privacy requires asking what data is collected, why, how it is used, and who can access it.", "تتطلب الخصوصية سؤال ما البيانات المجمعة ولماذا وكيف تستخدم ومن يصل إليها."), L("A black-box result is hard to check or challenge; Explainable AI helps people understand relevant reasons.", "يصعب التحقق من نتيجة الصندوق الأسود أو الاعتراض عليها؛ ويساعد الذكاء القابل للتفسير الناس على فهم الأسباب المهمة."), L("Fairness avoids unjust discrimination; transparency makes important decisions understandable.", "يتجنب الإنصاف التمييز غير المبرر؛ وتجعل الشفافية القرارات المهمة مفهومة."), L("Privacy protection and accountability keep personal data safe and people answerable for harmful outcomes.", "تحمي الخصوصية البيانات الشخصية وتبقي المساءلة الأشخاص مسؤولين عن النتائج الضارة.")],
};
const unit1ArabicTerms: Record<string, string> = {
  "personal computer": "الحاسوب الشخصي", "Internet and Web": "الإنترنت والويب", smartphone: "الهاتف الذكي", "cloud computing": "الحوسبة السحابية", "Moore's Law": "قانون مور", "edge computing": "الحوسبة الطرفية", AR: "الواقع المعزز", VR: "الواقع الافتراضي", qubit: "الكيوبت", "cashless payment": "الدفع غير النقدي",
  "Artificial Intelligence": "الذكاء الاصطناعي", "Machine Learning": "تعلم الآلة", "Deep Learning": "التعلم العميق", "neural network": "الشبكة العصبية", "Generative AI": "الذكاء الاصطناعي التوليدي", hallucination: "الهلوسة", "rule-based program": "برنامج قائم على القواعد", prediction: "التنبؤ", classification: "التصنيف", verification: "التحقق",
  "recommendation system": "نظام التوصية", "voice assistant": "المساعد الصوتي", "machine translation": "الترجمة الآلية", "face recognition": "التعرف على الوجه", "medical image analysis": "تحليل الصور الطبية", "predictive maintenance": "الصيانة التنبؤية", logistics: "اللوجستيات", "probabilistic prediction": "التنبؤ الاحتمالي", privacy: "الخصوصية", "human judgment": "الحكم البشري",
  "algorithmic bias": "التحيز الخوارزمي", "training data": "بيانات التدريب", "black-box problem": "مشكلة الصندوق الأسود", "Explainable AI": "الذكاء الاصطناعي القابل للتفسير", fairness: "الإنصاف", transparency: "الشفافية", accountability: "المساءلة", "proxy variable": "متغير بديل", responsibility: "المسؤولية",
};

function unit1Assessments(slug: keyof typeof unit1Teaching): Pick<CurriculumLesson, "practice" | "quiz" | "keyTerms" | "takeaway" | "summaryPoints"> {
  const data = unit1Teaching[slug]; const terms = data.facts;
  const practice = terms.slice(0, 6).map((term, index) => unit1Question(`practice-${index + 1}`, "mcq", `Which lesson concept is best described by: ${term}?`, `أي مفهوم في الدرس يُوصف أفضل بأنه: ${term}؟`, "a", `This item checks the meaning and use of ${term}.`, `يتحقق هذا السؤال من معنى واستخدام ${term}.`, [term, "A completely unrelated concept", "A physical decoration", "A guaranteed outcome"]));
  practice.push(
    unit1Question("practice-7", "true-false", `True or false: ${terms[0]} should be understood in its lesson context, not as an isolated word.`, `صح أم خطأ: يجب فهم ${terms[0]} في سياق الدرس لا ككلمة منفصلة.`, "a", "True. Use the concept together with its purpose, evidence, limits, and effects.", "صحيح. استخدم المفهوم مع غرضه ودليله وحدوده وآثاره.", ["True", "False"]),
    unit1Question("practice-8", "cloze", `Fill in the blank with the key term: ${terms[1]} is an important idea in this lesson.`, `أكمل بكتابة المصطلح الرئيسي: ${terms[1]} فكرة مهمة في هذا الدرس.`, terms[1].toLowerCase(), `Model answer: ${terms[1]}.`, `الإجابة النموذجية: ${terms[1]}.`),
    unit1Question("practice-9", "short", `In two or three sentences, explain why ${terms[2]} matters in this lesson.`, `في جملتين أو ثلاث، اشرح لماذا يعد ${terms[2]} مهمًا في هذا الدرس.`, terms[2].toLowerCase(), `A strong model answer names ${terms[2]}, explains its role, and connects it to a real situation from the lesson.`, `تسمي الإجابة النموذجية القوية ${terms[2]}، وتشرح دوره، وتربطه بموقف واقعي من الدرس.`),
    unit1Question("practice-10", "short", `Scenario: choose one lesson idea that would help a school make a responsible decision, and justify it with evidence.`, `سيناريو: اختر فكرة واحدة من الدرس تساعد مدرسة على اتخاذ قرار مسؤول وبررها بدليل.`, "model answer", "A strong answer identifies a suitable concept, its benefit, a limitation or risk, and a reasoned decision.", "تحدد الإجابة القوية مفهومًا مناسبًا وفائدته وقيدًا أو خطرًا وقرارًا مبررًا."),
  );
  const quiz = Array.from({ length: 10 }, (_, index) => { const term = terms[(index + 2) % terms.length]; return unit1Question(`quiz-${index + 1}`, index % 3 === 2 ? "true-false" : "mcq", index % 3 === 2 ? `True or false: ${term} has no limitations or ethical considerations.` : `Which Unit 1 idea should you use to explain ${term}?`, index % 3 === 2 ? `صح أم خطأ: ${term} لا توجد له حدود أو اعتبارات أخلاقية.` : `أي فكرة من الوحدة الأولى تستخدم لشرح ${term}؟`, index % 3 === 2 ? "b" : "a", index % 3 === 2 ? `${term} must be evaluated in context; technology and AI both have limits and human effects.` : `${term} is the correct lesson concept for this item.`, index % 3 === 2 ? `يجب تقييم ${term} في سياقه؛ فالتقنية والذكاء الاصطناعي لهما حدود وآثار بشرية.` : `${term} هو مفهوم الدرس الصحيح في هذا السؤال.`, index % 3 === 2 ? ["True", "False"] : [term, "An unrelated term", "A perfect guarantee", "A decorative feature"]); });
  return { practice, quiz, summaryPoints: unit1Summaries[slug], keyTerms: terms.slice(0, 6).map((term) => ({ term: L(term, unit1ArabicTerms[term] ?? term), definition: L(`A central concept for understanding ${slug.replaceAll("-", " ")}.`, `مفهوم أساسي لفهم ${slug.replaceAll("-", " ")}.`) })), takeaway: L(`Use Unit 1 ideas together: explain the technology, its benefit, its limits, and its effect on people.`, `استخدم أفكار الوحدة الأولى معًا: اشرح التقنية وفائدتها وحدودها وأثرها في الناس.`) };
}

export const part1Lessons: CurriculumLesson[] = specs.map(build).map((lesson): CurriculumLesson => {
  if (lesson.slug in unit1Teaching) {
    const detailed = unit1Teaching[lesson.slug as keyof typeof unit1Teaching];
    const finalStage = unit1LessonOverrides[lesson.slug];
    // The original content source can be extended independently; prevent an
    // accidental identical section from becoming a second lesson card.
    const explanation = detailed.explanation.filter((item, index, items) => items.findIndex((candidate) => candidate.title.en === item.title.en && candidate.body.en === item.body.en && candidate.visual === item.visual) === index);
    return { ...lesson, objectives: [...detailed.objectives], explanation: explanation.map((item) => ({ ...item })), ...unit1Assessments(lesson.slug as keyof typeof unit1Teaching), ...finalStage };
  }
  const unit2 = unit2LessonOverrides[lesson.slug];
  if (unit2) return { ...lesson, ...unit2 };
  const unit3 = unit3LessonOverrides[lesson.slug];
  const unit4 = unit4LessonOverrides[lesson.slug];
  return (unit4 ?? unit3) ? { ...lesson, ...(unit4 ?? unit3) } : lesson;
});
export const unit1Lessons = part1Lessons;
export const getLessonBySlug = (slug: string) => part1Lessons.find((lesson) => lesson.slug === slug);
export const getLessonById = (id: string) => part1Lessons.find((lesson) => lesson.id === id);
export const toLearnerLesson = (lesson: CurriculumLesson) => lesson;
export const lessonCount = part1Lessons.length;
export const localeText = (locale: Locale, value: LocalizedText) => value[locale];
